const API_BASE=window.location.hostname==="localhost"||window.location.hostname==="127.0.0.1"?"http://localhost:8000":"https://goexpressly.onrender.com";const Api={_getToken(){return localStorage.getItem("gx_token")},_headers(extra={}){const token=this._getToken();return{"Content-Type":"application/json",...token?{Authorization:`Bearer ${token}`}:{},...extra}},async _request(method,path,body=null,formData=false){const opts={method:method,headers:formData?{}:this._headers()};if(body&&formData){const token=this._getToken();if(token)opts.headers.Authorization=`Bearer ${token}`;opts.body=body}else if(body){opts.body=JSON.stringify(body)}const res=await fetch(`${API_BASE}${path}`,opts);if(res.status===204)return null;const data=await res.json().catch(()=>({}));if(!res.ok)throw{status:res.status,detail:data.detail||"An error occurred"};return data},async login(email,password){const form=new URLSearchParams;form.append("username",email);form.append("password",password);const res=await fetch(`${API_BASE}/api/auth/login`,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:form.toString()});const data=await res.json();if(!res.ok)throw{status:res.status,detail:data.detail||"Login failed"};localStorage.setItem("gx_token",data.access_token);return data},async getMe(){return this._request("GET","/api/auth/me")},logout(){localStorage.removeItem("gx_token");window.location.href="/login"},isAuthenticated(){return!!this._getToken()},async trackPackage(trackingId){return this._request("GET",`/api/track/${encodeURIComponent(trackingId)}`)},async submitContactForm(data){return this._request("POST","/api/contact",data)},async listPackages(page=1,pageSize=20){return this._request("GET",`/api/packages?page=${page}&page_size=${pageSize}`)},async createPackage(data){return this._request("POST","/api/packages",data)},async getPackage(id){return this._request("GET",`/api/packages/${id}`)},async updatePackage(id,data){return this._request("PATCH",`/api/packages/${id}`,data)},async deletePackage(id){return this._request("DELETE",`/api/packages/${id}`)},async addEvent(packageId,data){return this._request("POST",`/api/packages/${packageId}/events`,data)},async listEvents(packageId){return this._request("GET",`/api/packages/${packageId}/events`)}};